 44→export const loader = async ({ request }: LoaderFunctionArgs) => {
 45→  const { session } = await authenticate.admin(request);
 46→  const shop = session.shop;
 47→
 48→  const rules = await db.deliveryRule.findMany({
 49→    where: { shop },
 50→    orderBy: { priority: "asc" },
 51→  });
 52→
 53→  // Get unique zones from zip codes for dropdown
 54→  const zones = await db.zipCode.findMany({
 55→    where: { shop, zone: { not: null } },
 56→    select: { zone: true },
 57→    distinct: ["zone"],
 58→  });
 59→
 60→  return {
 61→    rules,
 62→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
 63→  };
 64→};
 65→
 66→export const action = async ({ request }: ActionFunctionArgs) => {
 67→  const { session } = await authenticate.admin(request);
 68→  const shop = session.shop;
 69→  const formData = await request.formData();
 70→  const intent = formData.get("intent");
 71→
 72→  if (intent === "create" || intent === "update") {
 73→    const id = String(formData.get("id") || "");
 74→    const name = String(formData.get("name") || "").trim();
 75→    const zone = String(formData.get("zone") || "").trim() || null;
 76→    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
 77→    const minOrderAmount = formData.get("minOrderAmount")
 78→      ? parseFloat(String(formData.get("minOrderAmount")))
 79→      : null;
 80→    const deliveryFee = formData.get("deliveryFee")
 81→      ? parseFloat(String(formData.get("deliveryFee")))
 82→      : null;
 83→    const freeShippingAbove = formData.get("freeShippingAbove")
 84→      ? parseFloat(String(formData.get("freeShippingAbove")))
 85→      : null;
 86→    const estimatedDays =
 87→      String(formData.get("estimatedDays") || "").trim() || null;
 88→    const cutoffTime =
 89→      String(formData.get("cutoffTime") || "").trim() || null;
 90→    const daysOfWeek =
 91→      String(formData.get("daysOfWeek") || "").trim() || null;
 92→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
 93→
 94→    if (!name) return { error: "Rule name is required." };
 95→
 96→    const data = {
 97→      name,
 98→      zone,
 99→      zipCodes,
100→      minOrderAmount,
101→      deliveryFee,
102→      freeShippingAbove,
103→      estimatedDays,
104→      cutoffTime,
105→      daysOfWeek,
106→      priority,
107→    };
108→
109→    if (intent === "update" && id) {
110→      await db.deliveryRule.update({ where: { id }, data });
111→      return { success: true, action: "updated" };
112→    } else {
113→      await db.deliveryRule.create({ data: { shop, ...data } });
114→      return { success: true, action: "created" };
115→    }
116→  }
117→
118→  if (intent === "delete") {
119→    const id = String(formData.get("id"));
120→    await db.deliveryRule.delete({ where: { id } });
121→    return { success: true, action: "deleted" };
122→  }
123→
124→  if (intent === "toggle") {
125→    const id = String(formData.get("id"));
126→    const isActive = formData.get("isActive") === "true";
127→    await db.deliveryRule.update({
128→      where: { id },
129→      data: { isActive: !isActive },
130→    });
131→    return { success: true, action: "toggled" };
132→  }
133→
134→  return null;
135→};
