 361→            }}
 362→          >
 363→            <div id={wid} style={{ maxWidth: "300px" }}>
 364→              <p className="zcc-heading" style={{ marginBottom: "12px" }}>
 365→                {cfg.heading}
 366→              </p>
 367→              <div className="zcc-row">
 368→                <input
 369→                  className="zcc-input"
 370→                  type="text"
 371→                  placeholder={cfg.placeholder}
 372→                  readOnly
 373→                />
 374→                <button className="zcc-btn" type="button">
